import{_ as t,o as i,c as e,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const o="/bzygq/assets/quesion_imgs_image_1769735201127_0_1769735201138_664.KEmf0vrp.png",l="/bzygq/assets/quesion_imgs_image_1769735202972_1_1769735202983_874.CvXPn52L.png",s="/bzygq/assets/quesion_imgs_image_1769735204147_2_1769735204155_160.CamXyKeH.png",n="/bzygq/assets/quesion_imgs_image_1769735204866_3_1769735204879_718.DkfTzlVv.png",h="/bzygq/assets/quesion_imgs_image_1769735205951_4_1769735205958_803.CwIa0wwK.png",p="/bzygq/assets/quesion_imgs_image_1769735206638_5_1769735206647_838.cA1sp0sM.png",c="/bzygq/assets/quesion_imgs_image_1769735207847_6_1769735207862_475.B1POw2_o.png",_="/bzygq/assets/quesion_imgs_image_1769735208560_7_1769735208576_419.CmFCh0NL.png",g="/bzygq/assets/quesion_imgs_image_1769735209970_8_1769735209979_820.DTzBX-qE.png",v=JSON.parse('{"title":"3、活动网络（AOE）","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据结构/7、图/3、活动网络（AOE）.md","filePath":"科技岗专业课/数据结构/7、图/3、活动网络（AOE）.md","lastUpdated":1788883925000}'),d={name:"科技岗专业课/数据结构/7、图/3、活动网络（AOE）.md"};function u(m,a,q,b,A,P){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="_3、活动网络-aoe" tabindex="-1">3、活动网络（AOE） <a class="header-anchor" href="#_3、活动网络-aoe" aria-label="Permalink to &quot;3、活动网络（AOE）&quot;">​</a></h1><p><strong>活动网络（AOE）</strong></p><h2 id="活动网络概念" tabindex="-1">活动网络概念 <a class="header-anchor" href="#活动网络概念" aria-label="Permalink to &quot;活动网络概念&quot;">​</a></h2><h2 id="活动网络的定义" tabindex="-1">活动网络的定义 <a class="header-anchor" href="#活动网络的定义" aria-label="Permalink to &quot;活动网络的定义&quot;">​</a></h2><p>活动网络是<strong>项目管理、系统工程、流程优化</strong>等领域的核心工具，本质是通过<strong>有向图</strong>可视化呈现活动之间的逻辑依赖关系、时间参数及资源约束，核心用于进度规划、关键路径识别、资源优化分配，典型应用包括项目管理中的关键路径法（CPM）、计划评审技术（PERT）等。</p><p>它通过有向图（如AOE网络，Activity On Edge）表示活动间的时序约束，其中<strong>节点代表事件（如项目里程碑</strong>），边代表活动（如具体任务），边上的权值表示活动持续时间。通过计算关键路径（Critical Path），可以确定项目最短完成时间和关键活动。</p><p><img src="'+o+'" alt=""></p><p>在软件项目中，活动图通常用于描述业务流程、用例实现或程序的执行流程。通过活动图，我们可以清晰地看到项目从开始到结束的整个过程，包括各个活动之间的顺序关系、并行关系以及条件分支等。这种图形化的表示方式不仅提高了项目流程的可读性，还有助于团队成员之间的沟通与协作。明确 “哪些活动必须先完成才能启动下一个”“整个流程的最短工期是多少”“哪些活动延迟会影响整体进度”。</p><h2 id="活动网络的相关概念" tabindex="-1">活动网络的相关概念 <a class="header-anchor" href="#活动网络的相关概念" aria-label="Permalink to &quot;活动网络的相关概念&quot;">​</a></h2><h3 id="活动网络相关术语" tabindex="-1">活动网络相关术语 <a class="header-anchor" href="#活动网络相关术语" aria-label="Permalink to &quot;活动网络相关术语&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><h4 id="活动-activity-——带箭头的边" tabindex="-1">活动（Activity）——带箭头的边 <a class="header-anchor" href="#活动-activity-——带箭头的边" aria-label="Permalink to &quot;活动（Activity）——带箭头的边&quot;">​</a></h4><p>活动指的是项目中需要<strong>消耗时间、资源</strong>的具体任务单元，也是网络的基本组成部分，一般由带箭头的边组成，如上图示，带箭头的线段A就是一个活动，这个活动所需要的事件是4天，活动完成之后就完成了打地基这个事件。</p><h4 id="事件-node-——节点" tabindex="-1">事件（Node）——节点 <a class="header-anchor" href="#事件-node-——节点" aria-label="Permalink to &quot;事件（Node）——节点&quot;">​</a></h4><p>事件表示活动的<strong>开始、结束或衔接点</strong>，是网络图的 “连接点”，不同网络类型中，节点的含义完全不同，如上图所示，打地基、砌墙、水电、封顶都是建造房屋这个活动所必须的事件。</p><h4 id="紧前活动-predecessor-activity" tabindex="-1">紧前活动（Predecessor Activity） <a class="header-anchor" href="#紧前活动-predecessor-activity" aria-label="Permalink to &quot;紧前活动（Predecessor Activity）&quot;">​</a></h4><p>紧前活动必须<strong>先于某一活动完成</strong>，才能启动该活动的前置任务，比如砌墙依赖于打地基这个事件的完成，那么活动A就是活动B的紧前活动。</p><h4 id="紧后活动-successor-activity" tabindex="-1">紧后活动（Successor Activity） <a class="header-anchor" href="#紧后活动-successor-activity" aria-label="Permalink to &quot;紧后活动（Successor Activity）&quot;">​</a></h4><p>紧后活动是指某一活动<strong>完成后才能启动</strong>的后续任务，比如打地基完成之后，才能进行砌墙这个事件，那么活动B就是活动A的紧后活动。</p><h4 id="路径-path" tabindex="-1">路径（Path） <a class="header-anchor" href="#路径-path" aria-label="Permalink to &quot;路径（Path）&quot;">​</a></h4><p>从项目的<strong>起始节点</strong>到<strong>终止节点</strong>的一系列连续活动的集合，一个项目的活动网络中，通常存在多条路径。比如：</p><p>开始 - 打基地 - 砌墙 - 封顶，是一条路径；开始 - 打地基 - 水电 - 封顶是另外一条路径。</p><h4 id="关键路径-critical-path" tabindex="-1">关键路径（Critical Path） <a class="header-anchor" href="#关键路径-critical-path" aria-label="Permalink to &quot;关键路径（Critical Path）&quot;">​</a></h4><p>关键路径是指活动网络中<strong>总工期最长的路径</strong>。它的核心特点是：<strong>路径上的所有活动都没有弹性时间（时差为 0）</strong>，任何一个活动的延迟都会直接导致<strong>整个项目的工期延迟</strong>。关键路径活动网络分析的核心目标 —— 找到关键路径，就能把项目管理的重点放在这些 “不可延迟” 的活动上。后续我们将详细介绍如何找一个活动网络的关键路径。</p><h2 id="动网络示例" tabindex="-1">动网络示例 <a class="header-anchor" href="#动网络示例" aria-label="Permalink to &quot;动网络示例&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p>活动网络实际上就是用来描述各种活动和进度和前后依赖关系的方法，这里我们以一个简单的例子来介绍活动网络，假设要建造一栋房屋，活动网络可以描述如下：</p><ol><li>活动A：打地基（需5天）</li><li>活动B：砌墙（需10天，依赖A完成）</li><li>活动C：安装水电（需7天，依赖A完成）</li><li>活动D：封顶（需3天，依赖B和C完成）</li></ol><p>上图中每一个节点是一个事件，节点之间的带箭头的边是完成这项活动所需要的时间。其中有个非常重要的概念是——关键路径，关键路径上的任务能够按时完成，那么整个工程都能够按时完成，图中的关键路径为 A→B→D（总时长17天），若B延迟，整个项目将延期；而C有3天缓冲时间（非关键路径）。</p><h2 id="拓扑排序-topological-sorting" tabindex="-1">拓扑排序（Topological Sorting） <a class="header-anchor" href="#拓扑排序-topological-sorting" aria-label="Permalink to &quot;拓扑排序（Topological Sorting）&quot;">​</a></h2><p>拓扑排序是<strong>有向无环图（DAG）</strong> 的核心算法之一，本质是对 DAG 的顶点进行线性排序，使得对于图中任意一条有向边 u→v，顶点 u 在排序结果中始终位于顶点 v 之前。该算法是活动网络（如项目管理、任务调度）中 “依赖关系合规排序” 的核心支撑，与活动网络依赖关系（紧前 / 紧后活动）直接呼应，广泛应用于任务调度、编译依赖解析、工作流编排等场景。</p><h3 id="常用实现算法-简单步骤" tabindex="-1">常用实现算法（简单步骤） <a class="header-anchor" href="#常用实现算法-简单步骤" aria-label="Permalink to &quot;常用实现算法（简单步骤）&quot;">​</a></h3><h4 id="kahn-算法-入度法" tabindex="-1">Kahn 算法（入度法） <a class="header-anchor" href="#kahn-算法-入度法" aria-label="Permalink to &quot;Kahn 算法（入度法）&quot;">​</a></h4><ul><li>步骤 1：统计每个顶点的 “入度”（有多少条边指向它，代表 “前置依赖数”）。</li><li>步骤 2：把<strong>入度为 0</strong>的顶点加入队列（这些是 “没有前置任务” 的节点）。</li><li>步骤 3：从队列取顶点，加入排序序列；同时去掉该顶点的所有出边，更新对应顶点的入度。</li><li>步骤 4：重复步骤 2-3，直到队列空；若排序序列包含所有顶点，就是合法的拓扑排序。</li></ul><h4 id="深度优先搜索-dfs-法" tabindex="-1">深度优先搜索（DFS）法 <a class="header-anchor" href="#深度优先搜索-dfs-法" aria-label="Permalink to &quot;深度优先搜索（DFS）法&quot;">​</a></h4><ul><li>步骤 1：从任意未访问的顶点出发，递归遍历其所有后续顶点。</li><li>步骤 2：当一个顶点的所有后续顶点都遍历完毕，将它加入 “临时序列”。</li><li>步骤 3：遍历结束后，把临时序列<strong>反向输出</strong>，就是拓扑排序。</li></ul><h3 id="结合建房-aoe-图的示例" tabindex="-1">结合建房 AOE 图的示例 <a class="header-anchor" href="#结合建房-aoe-图的示例" aria-label="Permalink to &quot;结合建房 AOE 图的示例&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><p>之前的建房图（节点 1 = 开始、2 = 打地基完成、3 = 砌墙完成、4 = 水电完成、5 = 封顶完成）是 DAG，它的拓扑排序可以是：</p><ul><li>序列 1：1 → 2 → 3 → 4 → 5</li><li>序列 2：1 → 2 → 4 → 3 → 5</li></ul><p>这两个序列都满足 “前置事件在前、后续事件在后” 的依赖规则，拓补排序相对来说是比较简单的。</p><h2 id="关键路径" tabindex="-1">关键路径 <a class="header-anchor" href="#关键路径" aria-label="Permalink to &quot;关键路径&quot;">​</a></h2><h2 id="什么是关键路径" tabindex="-1">什么是关键路径？ <a class="header-anchor" href="#什么是关键路径" aria-label="Permalink to &quot;什么是关键路径？&quot;">​</a></h2><p><img src="'+h+'" alt=""></p><p><strong>关键路径（Critical Path）</strong> 是项目管理和图论中的核心概念，<strong>指项目计划中耗时最长的路径</strong>，决定了项目的最短完成时间。通俗来说，它是项目的“生命线”——路径上的任何活动延迟，都会直接导致整个项目延期。</p><p><strong>只要关键路径上的活动都完成了，其他路径上的活动也就完成了，因为耗时肯定比关键路径上的活动耗时小，此时才能说是完成了项目。</strong></p><p><strong>关键路径</strong>：是从“起点事件”到“终点事件”的<strong>最长路径</strong>——因为项目必须等这条路径上的所有活动都完成才能结束，这条路径的总耗时就是项目的最短工期。</p><p><strong>关键活动：<strong>关键路径上的活动——这些活动</strong>没有缓冲时间</strong>，一旦延迟，整个项目就会延期。</p><h2 id="求解关键路径的步骤" tabindex="-1">求解关键路径的步骤 <a class="header-anchor" href="#求解关键路径的步骤" aria-label="Permalink to &quot;求解关键路径的步骤&quot;">​</a></h2><ul><li>起点：顶点1；终点：顶点5</li><li>活动：A(4)（1→2）、B(10)（2→3）、C(7)（2→4）、D(3)（3→5）、D(3)（4→5）</li></ul><h1 id="步骤1-计算事件的最早发生时间-ve" tabindex="-1">步骤1：计算事件的最早发生时间（ve） <a class="header-anchor" href="#步骤1-计算事件的最早发生时间-ve" aria-label="Permalink to &quot;步骤1：计算事件的最早发生时间（ve）&quot;">​</a></h1><p><img src="'+p+'" alt=""></p><p>从起点正向计算，取“入边路径的最大值”为事件的最早发生时间（事件需等前置活动都完成才能发生）：</p><ul><li>（起点事件最早时间为0）</li></ul><h1 id="步骤2-计算事件的最迟发生时间-vl" tabindex="-1">步骤2：计算事件的最迟发生时间（vl） <a class="header-anchor" href="#步骤2-计算事件的最迟发生时间-vl" aria-label="Permalink to &quot;步骤2：计算事件的最迟发生时间（vl）&quot;">​</a></h1><p><img src="'+c+'" alt=""></p><p>从终点逆向计算，取“出边路径的最小值”（事件不能延误，否则会拖后总工期）：</p><ul><li>（终点事件最迟时间=最早时间）</li></ul><h1 id="步骤3-判断关键活动" tabindex="-1">步骤3：判断关键活动 <a class="header-anchor" href="#步骤3-判断关键活动" aria-label="Permalink to &quot;步骤3：判断关键活动&quot;">​</a></h1><p><img src="'+_+'" alt=""></p><p>活动的<strong>最早开始时间（e）= 起点事件的ve</strong>，<strong>最迟开始时间（l）= 终点事件的vl - 活动持续时间</strong>。</p><p>当 时，该活动是关键活动（延误则总工期延误）：</p><ul><li>活动A（1→2）： → （关键活动）</li><li>活动B（2→3）： → （关键活动）</li><li>活动C（2→4）： → （非关键）</li><li>活动D（3→5）： → （关键活动）</li><li>活动D（4→5）： → （非关键）</li></ul><h1 id="步骤4-确定关键路径" tabindex="-1">步骤4：确定关键路径 <a class="header-anchor" href="#步骤4-确定关键路径" aria-label="Permalink to &quot;步骤4：确定关键路径&quot;">​</a></h1><p>由关键活动（A、B、D（3→5））组成的路径：（对应活动A→B→D），即图右侧的关键路径。</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2016】拓扑排序是按 AOE 网中每个结点事件的最早发生时间对结点进行排序。A. 正确B. 错误答案 ：B解析 ：拓扑排序是对有向无环图(DAG)的顶点进行线性排序，使得对于图中任意一条有向边 u→v，顶点 u 在排序结果中始终位于顶点 v 之前。拓扑排序的顺序并不一定是按照 AOE 网中每个结点事件的最早发生时间排序。</th></tr></thead></table><p>【央国企笔试真题】某软件项目的活动图如下图所示，其中顶点表示项目里程碑，连接顶点的边表示包含的活动，边上的数字表示活动的持续时间（天），则完成该项目的最少时间为______天。活动BD最多可以晚开始_________天而不会影响整个项目的进度。</p><p><img src="'+g+'" alt=""></p><p>（1）A 15 B 21 C 22 D 24</p><p>（2）A 0 B 2 C 3 D 5</p><p><strong>（1）完成该项目的最少时间</strong></p><p>关键路径概念：在项目活动图中，关键路径是从开始顶点到结束顶点的最长路径，它决定了完成项目的最少时间 。因为关键路径上的活动一旦延迟，整个项目的完成时间就会延迟。</p><p>寻找关键路径：</p><ul><li>计算各条路径的持续时间：</li><li>路径：天。</li><li>路径：天。</li><li>路径：天。</li><li>路径：天。</li></ul><p>比较各路径持续时间，22天是最长的，所以关键路径是，完成该项目的最少时间为22天，答案选 C。</p><p><strong>（2）活动BD最多可以晚开始的天数</strong></p><p>总时差概念：活动的总时差是指在不影响整个项目完成时间（即不影响关键路径）的前提下，该活动可以延迟开始的最长时间。</p><p>计算BD总时差：</p><ul><li>关键路径是 ，活动BD在关键路径上。</li><li>关键路径上的活动总时差为0，这意味着在不影响整个项目进度的情况下，活动BD最多可以晚开始0天，答案选 A。</li></ul>',80)])])}const k=t(d,[["render",u]]);export{v as __pageData,k as default};
